"use client";

import { Star, User, Eye, X } from "lucide-react";
import { useState } from "react";
import Image from "next/image";
import { Review } from "@/lib/google-places";

interface ReviewsListProps {
    reviews: Review[];
    rating: number;
    totalRatings: number;
    googleReviewsUrl?: string;
}



export function ReviewsList({ reviews, rating, totalRatings, googleReviewsUrl }: ReviewsListProps) {
    const [showPreview, setShowPreview] = useState(false);

    // Naive embed attempt: append output=embed if not present
    // Note: This relies on Google Maps legacy support or specific URL patterns.
    // Ideally use Embed API.
    const embedUrl = googleReviewsUrl?.includes("output=embed")
        ? googleReviewsUrl
        : `${googleReviewsUrl}&output=embed`;

    return (
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-stone-gray/10">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h2 className="text-2xl font-bold text-deep-teak">Visitor Reviews</h2>
                    <div className="flex items-center gap-2 mt-2">
                        <div className="flex items-center gap-1">
                            <span className="text-3xl font-heading font-bold text-deep-teak">{rating}</span>
                            <div className="flex text-orange-400">
                                {[...Array(5)].map((_, i) => (
                                    <Star key={i} className={`w-5 h-5 ${i < Math.round(rating) ? "fill-current" : "text-gray-300"}`} />
                                ))}
                            </div>
                        </div>
                        <span className="text-stone-gray text-sm">({totalRatings.toLocaleString()} reviews)</span>
                    </div>
                    <div className="flex items-center gap-1 mt-1 text-xs text-stone-gray/50">
                        Powered by <span className="font-bold">Google</span>
                    </div>
                </div>

                {/* Direct Link to Google Reviews */}
                {googleReviewsUrl && (
                    <div className="flex gap-2">
                        <button
                            onClick={() => setShowPreview(true)}
                            className="px-4 py-2 border border-stone-gray/20 rounded-full text-sm font-bold text-stone-gray hover:bg-stone-gray/5 transition-colors flex items-center gap-2"
                        >
                            <Eye className="w-4 h-4" />
                            Preview
                        </button>
                        <a
                            href={googleReviewsUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="px-4 py-2 bg-white border border-stone-gray/20 rounded-full text-sm font-bold text-stone-gray hover:text-deep-teak hover:border-deep-teak transition-colors flex items-center gap-2"
                        >
                            <Image src="/images/google-g-logo.svg" width={16} height={16} alt="Google" className="opacity-80" />
                            Write a Review
                        </a>
                    </div>
                )}
            </div>

            <div className="space-y-6">
                {reviews.map((review, idx) => (
                    <div key={idx} className="border-b border-stone-gray/10 last:border-0 pb-6 last:pb-0">
                        <div className="flex items-start gap-4">
                            <div className="relative w-10 h-10 rounded-full overflow-hidden bg-stone-gray/10 shrink-0">
                                {review.profile_photo_url ? (
                                    // Google photos might be external, simple img tag or configured Next Image
                                    // eslint-disable-next-line @next/next/no-img-element
                                    <img
                                        src={review.profile_photo_url}
                                        alt={review.author_name}
                                        className="w-full h-full object-cover"
                                    />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-stone-gray">
                                        <User className="w-5 h-5" />
                                    </div>
                                )}
                            </div>
                            <div className="flex-1">
                                <div className="flex justify-between items-start mb-1">
                                    <h4 className="font-bold text-deep-teak">{review.author_name}</h4>
                                    <span className="text-xs text-stone-gray">{review.relative_time_description}</span>
                                </div>
                                <div className="flex text-orange-400 mb-2">
                                    {[...Array(5)].map((_, i) => (
                                        <Star key={i} className={`w-3 h-3 ${i < review.rating ? "fill-current" : "text-gray-300"}`} />
                                    ))}
                                </div>
                                <p className="text-stone-gray text-sm leading-relaxed">
                                    {review.text}
                                </p>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Preview Modal */}
            {showPreview && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-white rounded-3xl w-full max-w-4xl h-[80vh] flex flex-col shadow-2xl overflow-hidden">
                        <div className="p-4 border-b border-stone-gray/10 flex justify-between items-center bg-warm-white">
                            <h3 className="font-bold text-deep-teak flex items-center gap-2">
                                <Image src="/images/google-g-logo.svg" width={16} height={16} alt="Google" />
                                Google Maps Preview
                            </h3>
                            <button
                                onClick={() => setShowPreview(false)}
                                className="p-2 hover:bg-stone-gray/10 rounded-full text-stone-gray transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="flex-1 bg-stone-gray/5 relative">
                            <iframe
                                src={embedUrl}
                                title="Google Maps Preview"
                                className="w-full h-full"
                                style={{ border: 0 }}
                                allowFullScreen
                            />
                            {/* Fallback overlay in case it doesn't load/is blocked */}
                            <div className="absolute top-0 left-0 w-full p-2 bg-yellow-50 text-yellow-800 text-xs text-center border-b border-yellow-100 opacity-80 hover:opacity-100 transition-opacity">
                                If the preview is blank, Google may have blocked embedding for this specific link. <a href={googleReviewsUrl} target="_blank" className="underline font-bold">Open in new tab</a>.
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div >
    );
}
